/* Example: measure, create composite index, and re-measure */
-- 1) Measure
EXPLAIN ANALYZE SELECT id, amount FROM orders WHERE user_id = 123 AND status = 'open';

-- 2) Create a composite index (leftmost = user_id)
CREATE INDEX idx_orders_user_status ON orders(user_id, status) INCLUDE (amount);

-- 3) Re-run
EXPLAIN ANALYZE SELECT id, amount FROM orders WHERE user_id = 123 AND status = 'open';

-- 4) Inspect index stats (Postgres)
SELECT * FROM pg_stat_user_indexes WHERE indexrelname = 'idx_orders_user_status';
